<script lang="ts">
  import { availableStats } from '../lib/stat-explorer';
  import { statsForGeneration } from '../lib/stats';
  import type { HistoricalStatId } from '../lib/metadata';
  import { TYPE_BY_ID } from '../lib/metadata';
  import type { Pokemon, ViewMode } from '../lib/model';
  import { generation } from '../lib/generation-state';
  import { language, t } from '../lib/i18n';
  import { pokemonName, statName } from '../lib/localization';
  let { pokemon, view, x, y, onAxes, onOpen }: { pokemon: Pokemon[]; view: ViewMode; x: HistoricalStatId; y: HistoricalStatId; onAxes: (x: HistoricalStatId, y: HistoricalStatId) => void; onOpen: (id: number) => void } = $props();
  const points = $derived(pokemon.flatMap(pokemon => { const stats = statsForGeneration(pokemon, view === 'legacy' ? $generation : 'current'); const horizontal = stats?.find(stat => stat.id === x)?.value; const vertical = stats?.find(stat => stat.id === y)?.value; return horizontal === undefined || vertical === undefined ? [] : [{ pokemon, x: horizontal, y: vertical }]; }));
</script>
<section class="card scatter-section"><h2>{$t('scatterTitle')}</h2><p class="stat-note">{$t('scatterHelp')}</p><div class="scatter-axes"><label>{$t('horizontalAxis')}<select id="scatter-x" class="select" value={x} onchange={event => onAxes(event.currentTarget.value as HistoricalStatId, y)}>{#each availableStats(view, $generation) as stat}<option value={stat.id}>{statName(stat.id, $language)}</option>{/each}</select></label><label>{$t('verticalAxis')}<select id="scatter-y" class="select" value={y} onchange={event => onAxes(x, event.currentTarget.value as HistoricalStatId)}>{#each availableStats(view, $generation) as stat}<option value={stat.id}>{statName(stat.id, $language)}</option>{/each}</select></label></div><svg id="stat-scatter" viewBox="0 0 380 340" role="group" aria-label={$t('scatterTitle')}><title>{$t('scatterTitle')}</title>{#each [0, 85, 170, 255] as tick}<line class="radar-grid" x1="48" y1={290-tick/255*250} x2="338" y2={290-tick/255*250}/><text x="40" y={294-tick/255*250} text-anchor="end">{tick}</text><text x={48+tick/255*290} y="307" text-anchor="middle">{tick}</text>{/each}<path d="M48 40V290H338" class="scatter-axis"/><text x="193" y="332" text-anchor="middle">{statName(x, $language)}</text><text transform="translate(13 165) rotate(-90)" text-anchor="middle">{statName(y, $language)}</text>{#each points as point}{@const name = `${pokemonName(point.pokemon.name, $language)} · ${statName(x, $language)} ${point.x} · ${statName(y, $language)} ${point.y}`}<circle data-scatter-pokemon={point.pokemon.id} cx={48+point.x/255*290} cy={290-point.y/255*250} r="4" fill={TYPE_BY_ID[(view === 'legacy' ? point.pokemon.legacyTypes : point.pokemon.types)[0]].color} role="button" tabindex="0" aria-label={name} onclick={() => onOpen(point.pokemon.id)} onkeydown={event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); onOpen(point.pokemon.id); } }}><title>{name}</title></circle>{/each}</svg><p role="status">{$t('pokemonCount', { count: points.length })}</p></section>
